use vstd::prelude::*;

verus! {

    /// Rotate a vector of i32’s to the left by `offset` positions (modulo the length).
    ///
    /// If the input is empty, returns an empty vector.
    ///
    /// Specification:
    ///   - The result has the same length as the input.
    ///   - If the input length `n` is zero, the result is empty.
    ///   - Otherwise, for all `i < n`, result[i] = a[(i + offset) mod n].
    fn rotate(a: &Vec<i32>, offset: usize) -> Vec<i32> {
        let n = a.len();
        if n == 0 {
            // Empty input ⇒ empty output
            Vec::new()
        } else {
            // Compute offset mod n so we never do a % 0
            let off = offset % n;

            // Prepare a vector with capacity n
            let mut res: Vec<i32> = Vec::new();
            res.reserve(n);

            // Build the rotated result by pushing one element at a time
            let mut i: usize = 0;
            while i < n
                invariant i <= n
                invariant res.len() == i
                invariant forall(|j: usize| j < i ==> res[j] == a[(j + off) % n])
                decreases n - i
            {
                // push the element from the rotated position
                res.push(a[(i + off) % n]);
                i += 1;
            }

            res
        }
    }
    ensuring(|res: &Vec<i32>| 
        // same length
        res.len() == a.len() &&
        // if nonempty, elements are rotated mod n
        (a.len() == 0 ||
         forall(|i: usize| i < res.len() ==> res[i] == a[(i + offset) % a.len()]))
    );
}